def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context['supply'])
    day = int(day_context['day'])
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    if budget <= 0:
        return 0.0

    alive_opponents = []
    for oid, opp in opponents_status.items():
        if opp.get('alive'):
            alive_opponents.append(opp)

    if not alive_opponents:
        if hp <= 2 or no_water_days >= 2:
            return float(min(budget, DAILY_SALARY * 0.9))
        return float(min(budget, DAILY_SALARY * 0.35))

    prev_bids = []
    desperate_count = 0
    rich_count = 0
    for opp in alive_opponents:
        if opp.get('hp', 10) <= 2 or opp.get('no_water_days', 0) >= 2:
            desperate_count += 1
        if opp.get('budget', 0) >= budget:
            rich_count += 1
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            try:
                prev_bids.append(float(prev.get('bid')))
            except Exception:
                pass

    highest_prev = max(prev_bids) if prev_bids else 0.0
    avg_prev = sum(prev_bids) / len(prev_bids) if prev_bids else 0.0

    units = supply / float(WATER_REQ)
    ample_supply = units >= 1.8
    tight_supply = units <= 1.25

    urgency = 0
    if hp <= 2:
        urgency += 3
    elif hp <= 4:
        urgency += 2
    elif hp <= 6:
        urgency += 1
    if no_water_days >= 2:
        urgency += 3
    elif no_water_days >= 1:
        urgency += 1

    market_heat = 0
    if highest_prev >= 150:
        market_heat += 3
    elif highest_prev >= 100:
        market_heat += 2
    elif highest_prev >= 60:
        market_heat += 1
    if avg_prev >= 120:
        market_heat += 1
    if desperate_count >= 2:
        market_heat += 1
    if tight_supply:
        market_heat += 1
    if ample_supply:
        market_heat -= 1

    if urgency >= 5:
        bid = max(DAILY_SALARY * 1.15, highest_prev + 6.0)
    elif urgency >= 3:
        if market_heat >= 3:
            bid = max(DAILY_SALARY * 0.95, highest_prev + 3.0)
        else:
            bid = max(DAILY_SALARY * 0.72, avg_prev + 4.0)
    else:
        if market_heat >= 4:
            bid = DAILY_SALARY * 0.18
        elif market_heat >= 2:
            bid = DAILY_SALARY * 0.38
        else:
            if ample_supply:
                bid = max(DAILY_SALARY * 0.52, avg_prev + 2.0)
            else:
                bid = max(DAILY_SALARY * 0.42, avg_prev * 0.75)

    if rich_count >= 2 and urgency <= 2 and tight_supply:
        bid *= 0.75

    if day >= 8:
        bid *= 1.08
    if day >= 9 and urgency >= 2:
        bid *= 1.12

    reserve = 0.0
    days_left = max(0, 10 - day)
    if hp > 4 and no_water_days == 0:
        reserve = min(budget * 0.35, days_left * 18.0)
    max_affordable = max(0.0, budget - reserve)

    if urgency >= 5:
        max_affordable = budget

    bid = min(bid, max_affordable)
    bid = min(bid, budget)
    bid = max(0.0, bid)
    return float(round(bid, 2))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MIN_SUPPLY = 15
    MAX_SUPPLY = 25

    supply = float(day_context.get('supply', 0.0))
    day = int(day_context.get('day', 0))

    hp = int(my_status.get('hp', 0))
    budget = float(my_status.get('budget', 0.0))
    no_water_days = int(my_status.get('no_water_days', 0))

    alive_opps = []
    for opp_id, opp in opponents_status.items():
        if opp.get('alive', False):
            alive_opps.append((opp_id, opp))

    if not alive_opps:
        return min(budget, DAILY_SALARY * 0.4)

    yesterday_bids = []
    yesterday_pressures = []
    for _, opp in alive_opps:
        prev = opp.get('previous_trace', {}) or {}
        bid = prev.get('bid', None)
        if bid is not None:
            try:
                yesterday_bids.append(float(bid))
            except Exception:
                pass
        # Use yesterday hp_after as a proxy for how costly it was to them
        hp_after = prev.get('hp_after', None)
        if hp_after is not None:
            try:
                yesterday_pressures.append(float(hp_after))
            except Exception:
                pass

    # If others were spending a lot yesterday, they likely expect to win shares again.
    if yesterday_bids:
        max_prev_bid = max(yesterday_bids)
        avg_prev_bid = sum(yesterday_bids) / max(1, len(yesterday_bids))
    else:
        max_prev_bid = 0.0
        avg_prev_bid = 0.0

    # Base bid: tie to supply availability.
    # With medium supply (15-25), aim for a moderate bid unless my hp is critical.
    supply_factor = (supply - MIN_SUPPLY) / max(1e-9, (MAX_SUPPLY - MIN_SUPPLY))
    supply_factor = max(0.0, min(1.0, supply_factor))

    # Determine aggressiveness from my condition.
    critical = (hp <= 2) or (no_water_days >= 2)
    strained = (hp <= 4) or (no_water_days >= 1)

    # Exploit: if Cindy/Alex were high yesterday (max_prev_bid large), they may outbid each other.
    # I can stay below their peak but above a floor.
    if max_prev_bid >= DAILY_SALARY * 2.0:  # ~180
        base = DAILY_SALARY * (0.45 + 0.15 * supply_factor)
        if critical:
            base = DAILY_SALARY * 0.85
        elif strained:
            base = DAILY_SALARY * 0.65
        # Cap under the max_prev_bid to avoid overpaying.
        bid = min(base, max_prev_bid * 0.75)
    elif max_prev_bid >= DAILY_SALARY * 1.2:  # ~108
        base = DAILY_SALARY * (0.40 + 0.10 * supply_factor)
        if critical:
            base = DAILY_SALARY * 0.75
        elif strained:
            base = DAILY_SALARY * 0.55
        bid = min(base, max_prev_bid * 0.85)
    else:
        base = DAILY_SALARY * (0.35 + 0.08 * supply_factor)
        if critical:
            base = DAILY_SALARY * 0.70
        elif strained:
            base = DAILY_SALARY * 0.50
        # If others are not spending, slightly undercut average.
        bid = min(base, avg_prev_bid * 0.9) if avg_prev_bid > 0 else base

    # Ensure we don't bid more than we can afford.
    bid = float(bid)
    if bid < 0:
        bid = 0.0
    bid = min(bid, budget)

    # Safety floor: if budget is decent and I'm not critical, still bid enough to avoid starvation.
    if not critical and budget >= DAILY_SALARY * 0.6:
        bid = max(bid, DAILY_SALARY * 0.30)
    if critical:
        bid = max(bid, min(budget, DAILY_SALARY * 0.60))

    return bid

